tool_and_message_events.command:
/bin/bash -lc "node --input-type=module - <<'NODE'
import {readFileSync} from 'node:fs'
const run=JSON.parse(readFileSync('visits/39895715-87bc-4327-a560-50afacd4592b.json','utf8'))
for (const [i,{action,state}] of run.timeline.entries()) {
  const diagnostic = action.target === 'text=Read diagnostics';
  const view = state.page.split('\\n').filter(line => line.endsWith(' notes'));
  console.log(i,state.width,JSON.stringify(action),diagnostic ? state.page.split('\\n').at(-1) : JSON.stringify(view));
}
console.log(JSON.stringify({error:run.error, requested:run.requested.length, completed:run.actions.length}))
NODE"

